import{_ as a,o as s,c as r,a2 as t}from"./chunks/framework.doxMM-x8.js";const u=JSON.parse('{"title":"Back Up Offline and Restore to a New Directory","description":"","frontmatter":{"docLocale":"en","counterpart":"/guides/server-operations","contentType":"guide","prev":{"text":"Node operational records and lifecycle","link":"/en/guides/server-traceability"},"next":{"text":"Web and same-origin hosting","link":"/en/guides/server-web"}},"headers":[],"relativePath":"en/guides/server-operations.md","filePath":"en/guides/server-operations.md"}'),i={name:"en/guides/server-operations.md"};function n(o,e,d,p,c,l){return s(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="back-up-offline-and-restore-to-a-new-directory" tabindex="-1">Back Up Offline and Restore to a New Directory <a class="header-anchor" href="#back-up-offline-and-restore-to-a-new-directory" aria-label="Permalink to &quot;Back Up Offline and Restore to a New Directory&quot;">​</a></h1><p>Goal: back up current Node data and restore it to a separate directory. Complete <a href="./server-traceability">Node operational records</a> first. Prepare a published asset and acknowledged business records. Use the pinned Node 24 and pnpm. Run these Bash commands from the repository root. They write the selected archive and restore directories.</p><h2 id="create-an-offline-archive" tabindex="-1">Create an Offline Archive <a class="header-anchor" href="#create-an-offline-archive" aria-label="Permalink to &quot;Create an Offline Archive&quot;">​</a></h2><p>Stop the service using the source directory. Press Ctrl+C in the terminal running <code>pnpm dev</code>. Wait for the process to exit.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_WORD_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/archives/lab-backup</span></span></code></pre></div><p>Success reports <code>status: backed-up</code>. The archive is a directory with <code>manifest.json</code>, a database snapshot and verified object bytes. The command holds source-directory exclusion. It reads ready references in pages, then streams size and SHA256 checks. Database transactions do not wait for file reads. Backup fails while an active service owns the source.</p><p>Output can be new or an existing empty directory. The safe <code>dataDir/backups</code> folder is allowed. Output and temporary archives cannot overlap the copied <code>pgdata</code> tree. Aliases resolve to real locations to prevent recursive copying. Publication removes only a confirmed empty output directory. It never recursively removes existing content.</p><p>The archive positively includes the database and ready objects. It excludes the raw <code>secrets/file-signing-key</code>, upload staging, logs and environment files. Password, session and API-key hashes remain persisted identity data inside the database.</p><h2 id="restore-and-read-back" tabindex="-1">Restore and Read Back <a class="header-anchor" href="#restore-and-read-back" aria-label="Permalink to &quot;Restore and Read Back&quot;">​</a></h2><p>Choose a new or empty directory. Use a destination separate from the original service directory.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_WORD_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.scratch/restored-lab</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --archive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/archives/lab-backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Success reports <code>status: restored</code>. Restore rejects linked directories at each archive path component. It checks format, paths and every file, then verifies the size and SHA256 of the actual staged copies. It checks database history and ready references in owned staging. It reserves destination exclusion without creating the destination and publishes the validated directory with one rename. A failed publication keeps a new destination absent or recreates the original empty directory. Nonempty destinations, wrong content and unsupported history fail. Correct the input or select a new directory, then retry.</p><p>On Linux, SIGTERM/SIGINT cancels archive work, drains the current copy and closes database and directory owners before exit. An abrupt process exit can leave a <code>.lab-word-backup-*.json</code> or <code>.lab-word-restore-*.json</code> ownership ledger beside its temporary directory. Retry the same command and destination after the old process has stopped. The command holds both destination and staging exclusion while reconciling a valid matching ledger, verifies the directory&#39;s recorded creation identity, restores a previous empty destination if publication was interrupted, then removes its owned staging. A live staging consumer blocks recovery. Missing or changed creation identity refuses cleanup and preserves the directory. Unknown directories and invalid or unrelated ledgers are preserved. Windows process termination uses this abrupt-exit recovery path. A directory already published successfully is preserved and remains a nonempty destination.</p><p>Log in with the original account. Open its Lab and download the asset. Identity and bytes remain the same. Retry an acknowledged Command with its original key and parameters to receive the original result. Startup interrupts old Runs. It does not replay Commands or resume long Tasks. A fresh signer issues new byte URLs.</p><p>The current build uses one <code>0000_baseline</code> migration. Startup and migration check existing applied history before running migration SQL. Earlier Node histories and archives are unsupported and are refused without conversion or target publication. Preserve those directories and archives; use their original source version to read them. Select a new data directory for this baseline. These commands do not convert or delete earlier Node or Rust/PostgreSQL data.</p><h2 id="migrate-and-recover-a-password" tabindex="-1">Migrate and Recover a Password <a class="header-anchor" href="#migrate-and-recover-a-password" aria-label="Permalink to &quot;Migrate and Recover a Password&quot;">​</a></h2><p>The same entrypoint provides serve, migrate and reset-password. <code>pnpm server</code> starts the service by default. Stop the service, then run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">read</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recovery_password</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s\\n&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$recovery_password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset-password</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> member@example.test</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recovery_password</span></span></code></pre></div><p>Migration reports the verified schema version. It does not start devices or maintenance loops. Password recovery reads standard input and excludes the password from output. It preserves user identity, revokes old sessions and records a system audit. Restart the service and log in with the new password. The original <code>pnpm reset-password --email ...</code> entrypoint remains available.</p><p>Owners: <a href="https://github.com/CaiZongyuan/labworld/blob/7f8c7a8f69b922a79e62f596722b42a6c8b26d46/apps/server/src/cli.ts" target="_blank" rel="noreferrer">unified CLI</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/7f8c7a8f69b922a79e62f596722b42a6c8b26d46/apps/server/src/operations.ts" target="_blank" rel="noreferrer">archive composition</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/7f8c7a8f69b922a79e62f596722b42a6c8b26d46/apps/server/src/archive-workspace.ts" target="_blank" rel="noreferrer">staging ownership and recovery</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/7f8c7a8f69b922a79e62f596722b42a6c8b26d46/apps/server/src/password-operation.ts" target="_blank" rel="noreferrer">shared password operation</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/7f8c7a8f69b922a79e62f596722b42a6c8b26d46/packages/server/src/platform/db/index.ts" target="_blank" rel="noreferrer">database history and opening</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/7f8c7a8f69b922a79e62f596722b42a6c8b26d46/packages/server/src/platform/db/snapshot.ts" target="_blank" rel="noreferrer">closed database snapshot</a>, and <a href="https://github.com/CaiZongyuan/labworld/blob/7f8c7a8f69b922a79e62f596722b42a6c8b26d46/packages/server/src/core/files/archive.ts" target="_blank" rel="noreferrer">Files ready references</a>.</p><h2 id="own-startup-and-shutdown-resources" tabindex="-1">Own Startup and Shutdown Resources <a class="header-anchor" href="#own-startup-and-shutdown-resources" aria-label="Permalink to &quot;Own Startup and Shutdown Resources&quot;">​</a></h2><p>Startup acquires directory exclusion and migrates the database. It completes device interruption recovery, then starts the separate schedulers, device loop, subscriptions and HTTP. Each owner registers cleanup when it acquires its resource. Later preparation failures still invoke those actions.</p><p>Shutdown stops HTTP admission, ends subscriptions and stops service timers and device admission. It attempts every registered owner&#39;s cleanup. One error does not skip another owner. Admitted HTTP validation, reports and database operations settle before database closure and lease release. Results and logs retain startup or shutdown failures. A failed exit does not report success.</p><p>Composition lives in <a href="https://github.com/CaiZongyuan/labworld/blob/7f8c7a8f69b922a79e62f596722b42a6c8b26d46/apps/server/src/runtime.ts" target="_blank" rel="noreferrer">runtime</a>. Existing prepared.stop callbacks remain supported. New owners register RuntimeControl.ownStop immediately after acquisition.</p><hr><p>Source version：<code>7f8c7a8f69b9</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/7f8c7a8f69b922a79e62f596722b42a6c8b26d46/docs/guides/server-operations.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,26)])])}const k=a(i,[["render",n]]);export{u as __pageData,k as default};
